import {createRequire} from 'node:module';
import type {ToolDefinition} from '../../types/ai.js';
import type {OutgoingMessage} from '../../types/messages.js';
import {log} from '../../shared/logger.js';

export interface ToolResponse {
  result: string;
  clientMessages?: OutgoingMessage[];
  suppressAssistantResponse?: boolean;
}

export interface ToolContext {
  userId: string | number;
  sessionId?: string;
  workspaceId?: string | number;
  authHeaders?: {
    cookie?: string;
    authorization?: string;
    host?: string;
  };
}

export type ToolExecutor = (input: Record<string, unknown>, context?: ToolContext) => Promise<string | ToolResponse>;

export function normalizeToolResponse(response: string | ToolResponse): ToolResponse {
  return typeof response === 'string' ? {result: response} : response;
}

export type ToolDefinitionSource = ToolDefinition | (() => ToolDefinition);

export interface RegisteredTool {
  definition: ToolDefinition;
  execute: ToolExecutor;
}

interface SchemaValidationError {
  keyword: string;
  instancePath?: string;
  dataPath?: string;
  params?: Record<string, unknown>;
}

interface CompiledValidator {
  (input: unknown): boolean;
  errors?: SchemaValidationError[] | null;
}

interface StoredTool {
  definitionSource: ToolDefinitionSource;
  execute: ToolExecutor;
  resolveValidator: () => CompiledValidator;
}

export class ToolRegistry {
  private readonly tools = new Map<string, StoredTool>();
  private readonly schemaCache = new WeakMap<Record<string, unknown>, CompiledValidator>();

  private resolveDefinition(source: ToolDefinitionSource): ToolDefinition {
    return typeof source === 'function' ? source() : source;
  }

  register(definition: ToolDefinitionSource, execute: ToolExecutor): void {
    const resolved = this.resolveDefinition(definition);
    const resolveValidator = buildValidatorResolver(this.schemaCache, definition, resolved);
    this.tools.set(resolved.name, {definitionSource: definition, execute, resolveValidator});
  }

  get(name: string): RegisteredTool | undefined {
    const tool = this.tools.get(name);
    if (!tool) return undefined;
    return {definition: this.resolveDefinition(tool.definitionSource), execute: tool.execute};
  }

  getDefinitions(): ToolDefinition[] {
    return [...this.tools.values()].map(t => this.resolveDefinition(t.definitionSource));
  }

  getPromptInstructions(): string[] {
    return this.getDefinitions()
      .filter(t => t.promptInstructions)
      .map(t => `${t.name}: ${t.promptInstructions}`);
  }

  getExamplePrompts(): string[] {
    return this.getDefinitions().flatMap(t => t.examplePrompts ?? []);
  }

  has(name: string): boolean {
    return this.tools.has(name);
  }

  /** Validates input before running (see specs/hal-engine-tool-input-validation/spec.md); throws on unknown tool. */
  async execute(name: string, input: Record<string, unknown>, context?: ToolContext): Promise<ToolResponse> {
    const tool = this.tools.get(name);
    if (!tool) {
      log.warn('tool', 'tool not found', {name});
      throw new Error(`Unknown tool: ${name}`);
    }
    const validateInput = tool.resolveValidator();
    if (!validateInput(input)) return buildRejectionResponse(name, validateInput.errors);
    log.info('tool', 'executing', {name, inputKeys: Object.keys(input)});
    const rawResult = await tool.execute(input, context);
    const response = normalizeToolResponse(rawResult);
    log.info('tool', 'execution complete', {
      name,
      rawType: typeof rawResult,
      clientMessageCount: response.clientMessages?.length ?? 0,
      clientMessageTypes: response.clientMessages?.map(m => m.type) ?? [],
      suppressAssistantResponse: response.suppressAssistantResponse ?? false,
    });
    return response;
  }
}

function buildValidatorResolver(
  cache: WeakMap<Record<string, unknown>, CompiledValidator>,
  source: ToolDefinitionSource,
  initial: ToolDefinition
): () => CompiledValidator {
  if (typeof source === 'function') {
    return () => getCachedValidator(cache, source());
  }
  const compiled = compileSchema(initial.name, initial.inputSchema);
  return () => compiled;
}

function getCachedValidator(
  cache: WeakMap<Record<string, unknown>, CompiledValidator>,
  definition: ToolDefinition
): CompiledValidator {
  const cached = cache.get(definition.inputSchema);
  if (cached) return cached;
  const compiled = compileSchema(definition.name, definition.inputSchema);
  cache.set(definition.inputSchema, compiled);
  return compiled;
}

interface AjvInstance {
  compile(schema: Record<string, unknown>): CompiledValidator;
}

type AjvConstructor = new (options: {
  strict: boolean;
  validateFormats: boolean;
  allErrors: boolean;
}) => AjvInstance;

const nodeRequire = createRequire(import.meta.url);
const Ajv = nodeRequire('ajv') as AjvConstructor;
const ajv = new Ajv({strict: false, validateFormats: false, allErrors: true});

function compileSchema(toolName: string, schema: Record<string, unknown>): CompiledValidator {
  try {
    return ajv.compile(schema);
  } catch (error) {
    const detail = error instanceof Error ? error.message : String(error);
    throw new Error(`Invalid inputSchema for tool "${toolName}": ${detail}`, {cause: error});
  }
}

function buildRejectionResponse(name: string, errors: SchemaValidationError[] | null | undefined): ToolResponse {
  const failures = errors?.length ? errors.map(formatValidationError) : ['input failed schema validation'];
  log.warn('tool', 'input validation failed', {name, failures});
  return {result: `Invalid input for tool "${name}": ${failures.join('; ')}`};
}

type KeywordFormatter = (basePath: string, params: Record<string, unknown> | undefined) => string;

const keywordFormatters: Record<string, KeywordFormatter | undefined> = {
  required: formatRequiredConstraint,
  type: formatTypeConstraint,
  enum: formatEnumConstraint,
};

function formatValidationError(schemaError: SchemaValidationError): string {
  const basePath = normalizeErrorPath(schemaError);
  const formatter = keywordFormatters[schemaError.keyword];
  if (formatter) return formatter(basePath, schemaError.params);
  const target = basePath || '<root>';
  return `${target} failed ${schemaError.keyword} constraint`;
}

function formatRequiredConstraint(basePath: string, params: Record<string, unknown> | undefined): string {
  const requiredField = typeof params?.missingProperty === 'string' ? params.missingProperty : '<property>';
  const fieldPath = basePath ? `${basePath}.${requiredField}` : requiredField;
  return `${fieldPath} is required`;
}

function formatTypeConstraint(basePath: string, params: Record<string, unknown> | undefined): string {
  const expectedType = typeof params?.type === 'string' ? params.type : String(params?.type ?? 'expected type');
  const target = basePath || '<root>';
  return `${target} must be ${expectedType}`;
}

function formatEnumConstraint(basePath: string, params: Record<string, unknown> | undefined): string {
  const allowed = Array.isArray(params?.allowedValues) ? params.allowedValues.map(String).join(', ') : '';
  const target = basePath || '<root>';
  return allowed ? `${target} must be one of: ${allowed}` : `${target} failed enum constraint`;
}

function normalizeErrorPath(schemaError: SchemaValidationError): string {
  const rawPath = schemaError.instancePath ?? schemaError.dataPath ?? '';
  return rawPath.replace(/^[/.]/, '').replaceAll('/', '.');
}

