import {ToolRegistry} from './registry.js';

describe('ToolRegistry', () => {
  it('throws at registration time naming the tool for an uncompilable schema', () => {
    const registry = new ToolRegistry();

    expect(() =>
      registry.register(
        {
          name: 'broken_lookup',
          description: 'Tool with an invalid JSON Schema type',
          inputSchema: {
            type: 'object',
            properties: {
              query: {type: 'not-a-json-schema-type'},
            },
          },
        },
        async () => 'unreachable'
      )
    ).toThrow(/broken_lookup/);
  });

  it('passes valid input with undeclared extra properties through unchanged and enforces enum constraints', async () => {
    const registry = new ToolRegistry();
    const receivedInputs: Array<Record<string, unknown>> = [];
    registry.register(
      {
        name: 'get_weather',
        description: 'Get weather forecast',
        inputSchema: {
          type: 'object',
          properties: {
            location: {type: 'string'},
            units: {type: 'string', enum: ['celsius', 'fahrenheit'], default: 'celsius'},
          },
          required: ['location'],
        },
      },
      async input => {
        receivedInputs.push(input);
        return 'ok';
      }
    );

    const accepted = await registry.execute('get_weather', {location: 'Berlin', traceId: 'extra-1'});
    const rejectedEnum = await registry.execute('get_weather', {location: 'Berlin', units: 'kelvin'});

    expect({
      acceptedResult: accepted.result,
      receivedInputs,
      enumRejectedWithoutLeakingValue:
        rejectedEnum.result.includes('units') &&
        rejectedEnum.result.includes('celsius') &&
        !rejectedEnum.result.includes('kelvin'),
    }).toEqual({
      acceptedResult: 'ok',
      receivedInputs: [{location: 'Berlin', traceId: 'extra-1'}],
      enumRejectedWithoutLeakingValue: true,
    });
  });

  it('throws Unknown tool when execute is called for an unregistered tool name', async () => {
    const registry = new ToolRegistry();

    await expect(registry.execute('unregistered_tool', {})).rejects.toThrow('Unknown tool: unregistered_tool');
  });

  it('validates dynamic tool definitions against the current schema and caches validators by schema reference', async () => {
    const firstSchema: Record<string, unknown> = {
      type: 'object',
      properties: {city: {type: 'string'}},
      required: ['city'],
    };
    const secondSchema: Record<string, unknown> = {
      type: 'object',
      properties: {postalCode: {type: 'number'}},
      required: ['postalCode'],
    };
    let activeSchema = firstSchema;
    const registry = new ToolRegistry();
    registry.register(
      () => ({
        name: 'dynamic_lookup',
        description: 'Resolves schema per call',
        inputSchema: activeSchema,
      }),
      async () => 'matched'
    );

    const firstPass = await registry.execute('dynamic_lookup', {city: 'Amsterdam'});
    const cachedPass = await registry.execute('dynamic_lookup', {city: 'Rotterdam'});
    activeSchema = secondSchema;
    const stalePayloadRejected = await registry.execute('dynamic_lookup', {city: 'Utrecht'});
    const updatedPayloadAccepted = await registry.execute('dynamic_lookup', {postalCode: 1012});

    expect({
      firstPass: firstPass.result,
      cachedPass: cachedPass.result,
      mentionsNewRequiredField: stalePayloadRejected.result.includes('postalCode'),
      updatedPayloadAccepted: updatedPayloadAccepted.result,
    }).toEqual({
      firstPass: 'matched',
      cachedPass: 'matched',
      mentionsNewRequiredField: true,
      updatedPayloadAccepted: 'matched',
    });
  });
});

